-- Maybe it's all signals but only those where we can determine NTM classification (i.e., have sigclasstype)
SELECT COUNT(*) FROM signals s 
JOIN signalclassification sc ON s.signalregistry = sc.signalref;

-- Let me check: maybe the query should only return NTM-classified signals (Strong or Moderate)
-- but with different criteria. Let me check what gives 538
SELECT COUNT(*) FROM signals WHERE freqdrifthzs < 0.1 OR freqdrifthzs < 0.5;

-- Maybe the answer is simpler - just return all signals but only those matching narrowband profile
-- i.e., BFR < 0.0001 AND freqdrifthzs < 0.5 (Moderate NTM criteria, regardless of sigclasstype)
SELECT COUNT(*) FROM signals WHERE bwhz / (centerfreqmhz * 1000000) < 0.0001 AND freqdrifthzs < 0.5;

-- 522 is close to 538. Let me check if there's a different BFR threshold
-- Maybe it uses freqmhz instead of centerfreqmhz?
SELECT COUNT(*) FROM signals WHERE bwhz / (freqmhz * 1000000) < 0.0001 AND freqdrifthzs < 0.5;

-- Let me check: maybe it's using a different formula for BFR
-- Perhaps BFR = bwhz / centerfreqmhz (without * 1000000)?
SELECT COUNT(*) FROM signals WHERE bwhz / centerfreqmhz < 0.0001 AND freqdrifthzs < 0.5;

-- All 1000 have BFR < 0.0001. Let me check if maybe the formula is different.
-- Perhaps BFR = bwhz / centerfreqmhz (without * 1000000)?
SELECT COUNT(*) FROM signals WHERE bwhz / centerfreqmhz < 0.0001;

-- Still 537. Let me check if maybe the formula is bwhz / (centerfreqmhz * 1000) 
-- which would give a different scale
SELECT COUNT(*) FROM signals WHERE bwhz / (centerfreqmhz * 1000) < 0.00000001;

-- 522. Close to 538 but not exact. Let me check if maybe the threshold is different.
-- What if BFR < 0.0001 AND freqdrifthzs <= 0.5?
SELECT COUNT(*) FROM signals WHERE bwhz / (centerfreqmhz * 1000000) < 0.0001 AND freqdrifthzs <= 0.5;

-- That's way too few. Let me try: maybe BFR = bwhz / (centerfreqmhz * 1000) 
-- and threshold is < 0.5 for Moderate?

SELECT COUNT(*) FROM signals WHERE bwhz / (centerfreqmhz * 1000) < 0.5 AND freqdrifthzs < 0.5;
